 "content": "def transform(grid):
    """Draw the color-coded strokes; crossing of the 2 and vertical stroke is 4."""
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    points = {}
    for r in range(h):
        for c in range(w):
            if out[r][c] != 0:
                points.setdefault(out[r][c], []).append((r, c))

    # Color 1: short eastward stroke with a raised endpoint.
    for r, c in points.get(1, []):
        for dc in (1, 2):
            if 0 <= c + dc < w:
                out[r][c + dc] = 5
        if r > 0 and c + 2 < w:
            out[r - 1][c + 2] = 1

    # Color 2: westward stroke of length four, retaining its endpoint color.
    for r, c in points.get(2, []):
        for dc in (1, 2, 3):
            if c - dc >= 0:
                out[r][c - dc] = 5
        if c - 4 >= 0:
            out[r][c - 4] = 2

    # Color 3: down stroke, two cells of 5 then a matching endpoint.
    for r, c in points.get(3, []):
        for dr in (1, 2):
            if r + dr < h:
                out[r + dr][c] = 5
        if r + 3 < h:
            out[r + 3][c] = 3

    # Color 6: upward stroke, five cells of 5 then matching endpoint.
    for r, c in points.get(6, []):
        for dr in range(1, 6):
            if r - dr >= 0:
                out[r - dr][c] = 5
        if r - 6 >= 0:
            out[r - 6][c] = 6

    # The crossing of a color-2 horizontal stroke and a color-3/6 vertical
    # stroke becomes 4, with a southwest diagonal of 4s to the grid edge.
    vertical = points.get(3, []) + points.get(6, [])
    horizontal = points.get(2, [])
    for vr, vc in vertical:
        for hr, hc in horizontal:
            if vr == hr and min(vc, hc) <= vc <= max(vc, hc):
                # Require that the crossing lies on the westward segment from 2.
                if vc <= hc and hc - vc <= 4:
                    out[vr][vc] = 4
                    r, c = vr + 1, vc - 1
                    while r < h and c >= 0:
                        out[r][c] = 4
                        r += 1
                        c -= 1
    return out
"
